#define _GNU_SOURCE
#include <ctype.h>
#include <dlfcn.h>
#include <stddef.h>
#include <string.h>
#include <unistd.h>

static ssize_t (*real_readlink)(const char *, char *, size_t);
static ssize_t (*real_readlinkat)(int, const char *, char *, size_t);

static int is_proc_pid_exe(const char *path) {
    const char *cursor;
    if (strncmp(path, "/proc/", 6) != 0)
        return 0;
    cursor = path + 6;
    if (!isdigit((unsigned char)*cursor))
        return 0;
    while (isdigit((unsigned char)*cursor))
        ++cursor;
    return strcmp(cursor, "/exe") == 0;
}

ssize_t readlink(const char *path, char *buf, size_t size) {
    if (!real_readlink)
        real_readlink = dlsym(RTLD_NEXT, "readlink");
    if (is_proc_pid_exe(path))
        path = "/proc/self/exe";
    return real_readlink(path, buf, size);
}

ssize_t readlinkat(int fd, const char *path, char *buf, size_t size) {
    if (!real_readlinkat)
        real_readlinkat = dlsym(RTLD_NEXT, "readlinkat");
    if (is_proc_pid_exe(path)) {
        fd = AT_FDCWD;
        path = "/proc/self/exe";
    }
    return real_readlinkat(fd, path, buf, size);
}

